      ],
      "sibling_distinctions": [
        {
          "other_code": "N_176b3b81a37f7209",
          "rule": "本节点关注特定先进器件的三维结构形态及其专用制造集成；兄弟节点关注构成这些结构的通用基础工艺单元（如光刻、刻蚀本身）。"
        },
