    },
    {
      "node_code": "N_e12184442f9dcd6c",
      "definition": "研究晶圆切割后芯片的封装技术、互连结构及三维集成方法，涵盖从传统引线键合到先进Chiplet异质集成及晶圆级封装的全流程。",
      "boundary": "聚焦于后道（Back-end）封装与系统级集成。涵盖芯片保护、电气互连、散热管理及多芯片/多器件集成。边界包括：1. 传统与先进封装形式；2. 互连技术（键合/倒装/TSV）；3. 2.5D/3D集成架构。若内容涉及晶圆级前道制造或器件内部物理，则不在此列。",
      "includes": [
        "引线键合、倒装芯片（Flip-Chip）及球栅阵列（BGA）封装技术",
        "系统级封装（SiP）、2.5D/3D Chiplet异质集成及中介层技术",
        "晶圆级封装（WLP）及硅通孔（TSV）制造与互连"
      ],
      "excludes": [
        "晶圆级前道图形化制造（归入前道晶圆制造核心工艺）",
        "晶体管内部三维结构制造（归入先进微纳制造与结构）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_176b3b81a37f7209",
          "rule": "本节点处理晶圆切割后的芯片级封装与互连；兄弟节点处理晶圆状态下的前道制造。"
        },
        {
          "other_code": "N_98a006b4960fef587ef1",
          "rule": "本节点关注芯片外部或芯片间的集成互连；兄弟节点关注芯片内部有源器件的三维结构制造。"
        }
      ],
      "cross_boundary_rule": "若内容涉及TSV（硅通孔）的制造，因其属于晶圆级互连结构，通常归入本节点（若侧重TSV作为封装互连手段）；若TSV用于前道器件隔离，可能涉及前道，但通常TSV与封装/3D集成强相关，故主挂载本节点。"
    }
  ]
}
